#!/usr/bin/env bash
# =============================================================================
# 03_ssr_chloroplast_blast.sh
# Confirm that SSRs classified as mitochondria-exclusive have no similarity
# to the chloroplast genome (BLASTn of SSR flanking regions).
#
# Input:
#   chloroplast.fasta   - chloroplast genome
#   SSRs_exclusive.fasta - FASTA generated by MICRO-MINE with the flanking
#                          regions of the mitochondria-exclusive SSRs
# Output:
#   blast_chloroplast_result.tsv
#   ssrs_to_discard.txt (after running filter_blast_hits.py)
# =============================================================================

# 1. Build the chloroplast BLAST database
makeblastdb -in chloroplast.fasta -dbtype nucl -out db_chloroplast

# 2. Run BLASTn with the flanking sequences
blastn -query SSRs_exclusive.fasta \
       -db db_chloroplast \
       -outfmt "6 qseqid sseqid pident length mismatch gapopen qstart qend sstart send evalue bitscore" \
       -max_target_seqs 1 \
       -evalue 1e-5 \
       -out blast_chloroplast_result.tsv

# 3. Filter the hits (identity >= 80% and alignment length >= 30 bp)
python3 filter_blast_hits.py

# 4. Next step: primer design
